1	// Setup registry (DESIGN.md §"Setups", §"Candidate generation").
2	//
3	//   const setups = loadSetups(repoRoot, process.env);   // sorted by id
4	//
5	// Reads setups/*.json (candidate: false) and setups/candidates/*.json (candidate: true). Never throws on a
6	// missing provider variable: that candidate is returned with env {} and an "(unavailable: <VAR> not set)" label.
7	// Only variable names are ever reported, never values.
8	
9	import { existsSync, readdirSync, readFileSync } from "node:fs";
10	import { join } from "node:path";
11	import { providerEnv } from "../harness/provider";
12	
13	export interface RunnableSetup {
14	  id: string;
15	  label: string;
16	  harness: "claude-code" | "codex";
17	  model: string;
18	  rulesPath: string;
19	  extraRulesPath: string | null;
20	  env: Record<string, string>;
21	  candidate: boolean;
22	}
23	
24	interface SetupFile {
25	  id: string;
26	  label?: string;
27	  harness: "claude-code" | "codex";
28	  model: string;
29	  rules: string;
30	  append_rules?: string;
31	  env?: Record<string, string>;
32	}
33	
34	const REF = /\$\{([A-Za-z_][A-Za-z0-9_]*)\}/g;
35	
36	function readDir(dir: string, candidate: boolean): Array<{ file: SetupFile; candidate: boolean }> {
37	  if (!existsSync(dir)) return [];
38	  return readdirSync(dir)
39	    .filter((f) => f.endsWith(".json"))
40	    .sort()
41	    .map((f) => ({ file: JSON.parse(readFileSync(join(dir, f), "utf8")) as SetupFile, candidate }));
42	}
43	
44	function missingVars(file: SetupFile, env: Record<string, string | undefined>): string[] {
45	  const missing: string[] = [];
46	  for (const raw of Object.values(file.env ?? {})) {
47	    for (const m of raw.matchAll(REF)) {
48	      const name = m[1]!;
49	      const v = env[name];
50	      if ((v === undefined || v === "") && !missing.includes(name)) missing.push(name);
51	    }
52	  }
53	  return missing;
54	}
55	
56	export function loadSetups(root: string, env: Record<string, string | undefined>): RunnableSetup[] {
57	  const entries = [...readDir(join(root, "setups"), false), ...readDir(join(root, "setups", "candidates"), true)];
58	  const out: RunnableSetup[] = entries.map(({ file, candidate }) => {
59	    const missing = missingVars(file, env);
60	    let label = file.label ?? file.id;
61	    let resolved: Record<string, string> = {};
62	    if (missing.length > 0) {
63	      label += ` (unavailable: ${missing.join(", ")} not set)`;
64	    } else {
65	      try {
66	        resolved = providerEnv(file, env);
67	      } catch {
68	        label += " (unavailable: provider env could not be resolved)";
69	      }
70	    }
71	    return {
72	      id: file.id,
73	      label,
74	      harness: file.harness,
75	      model: file.model,
76	      rulesPath: join(root, file.rules),
77	      extraRulesPath: file.append_rules ? join(root, file.append_rules) : null,
78	      env: resolved,
79	      candidate,
80	    };
81	  });
82	  return out.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
83	}
